#[test]
fn a_malformed_op_is_a_decode_error() {
    let decode = |json: Value| surface::decode_command("group-c.ai-op", &json.to_string(), 0, None);
    // A supported kind with a missing field.
    assert!(decode(serde_json::json!({"op":{"kind":"setText","node":"text0001"}})).is_err());
    // A string where a number belongs.
    assert!(
        decode(
            serde_json::json!({"op":{"kind":"insertText","node":"text0001","at":"1","text":"x"}})
        )
        .is_err()
    );
    assert!(decode(serde_json::json!({"op":"setText"})).is_err());
    assert!(decode(serde_json::json!({"op":{"node":"text0001"}})).is_err());
}

#[test]
fn the_invocation_token_is_a_required_u32() {
    let decode = |json: Value| surface::decode_command("group-c.ai-op", &json.to_string(), 0, None);
    let op = serde_json::json!({"kind":"setText","node":"text0001","text":"x"});
    assert!(decode(serde_json::json!({"op": op, "invocation": 1})).is_ok());
    assert!(decode(serde_json::json!({"op": op, "invocation": 4_294_967_295_u64})).is_ok());
    for bad in [
        serde_json::json!({"op": op}),
        serde_json::json!({"op": op, "invocation": -1}),
        serde_json::json!({"op": op, "invocation": 1.5}),
        serde_json::json!({"op": op, "invocation": 4_294_967_296_u64}),
        serde_json::json!({"op": op, "invocation": "1"}),
        serde_json::json!({"op": op, "invocation": null}),
    ] {
        assert!(decode(bad.clone()).is_err(), "{bad}");
    }
}

#[test]
fn the_ai_op_envelope_is_closed() {
    let decode = |json: Value| surface::decode_command("group-c.ai-op", &json.to_string(), 0, None);
    let op = serde_json::json!({"kind":"setText","node":"text0001","text":"x"});
    // A stale merge flag from an older host must not be ignored.
    for stale in [
        serde_json::json!(true),
        serde_json::json!(false),
        serde_json::json!(1),
    ] {
        assert!(decode(serde_json::json!({"op": op, "invocation": 1, "merge": stale})).is_err());
    }
    assert!(decode(serde_json::json!({"op": op, "invocation": 1, "extra": 0})).is_err());
}

#[test]
fn a_refusal_echoes_only_its_own_token() {
    let mut native = abc_editor();
    let op = serde_json::json!({"kind":"setText","node":"missing1","text":"x"});
    for token in [1_u32, 42, u32::MAX] {
        let (handled, commit) = native.dispatch(&op_command(&op, token)).expect("dispatch");
        assert_eq!(handled, Handled::No);
        assert_eq!(
            refusals(&commit),
            vec![serde_json::json!({"cause":"unknownNode","invocation":token})]
        );
    }
}

fn clear_selection_command(json: &str) -> crate::ModelResult<Option<Command>> {
    surface::decode_command("group-c.ai-edit-clear-selection", json, 0, None)
}

#[test]
fn the_clear_selection_payload_is_empty() {
    assert!(clear_selection_command("{}").expect("decodes").is_some());
    for bad in ["[]", "null", r#"{"x":1}"#, "1"] {
        assert!(clear_selection_command(bad).is_err(), "{bad}");
    }
}

#[test]
fn the_clear_selection_command_drops_the_selection_only() {
    // Source applyAiOps' first update, `$setSelection(null)`, runs even for no ops.
    let mut native = abc_editor();
    let text = native
        .state()
        .view()
        .first_child(
            native
                .state()
                .view()
                .first_child(NodeKey::ROOT)
                .expect("paragraph"),
        )
        .expect("text");
    native
        .update(|tx| {
            tx.set_selection(Some(Selection::Range(RangeSelection::new(
                Point::text(text, Utf16Offset(0)),
                Point::text(text, Utf16Offset(2)),
            ))))?;
            Ok(())
        })
        .expect("select ab");
    let before = export(&native);
    let command = clear_selection_command("{}")
        .expect("decodes")
        .expect("command");
    let (handled, commit) = native.dispatch(&command).expect("dispatch");
    assert_eq!(handled, Handled::Yes);
    assert_eq!(native.state().selection(), None);
    assert!(commit.selection_changed);
    assert_eq!(export(&native), before);
    assert!(commit.tags.is_empty());
    // Already clear: still handled, still no document change.
    let (handled, _) = native.dispatch(&command).expect("dispatch");
    assert_eq!(handled, Handled::Yes);
    assert_eq!(export(&native), before);
}

const BLOCK_CORPUS: &str = include_str!("corpus/blocks.app.json");

/// Every node type Source `nodeIdPlugin` gives an id in the block corpus.
const BLOCK_ID_CLASSES: [&str; 14] = [
    "root",
    "paragraph",
    "text",
    "heading",
    "quote",
    "custom-code",
    "code-highlight",
    "equation",
    "horizontalrule",
    "listitem",
    "task-list",
    "table",
    "tablerow",
    "tablecell",
];

#[derive(serde::Deserialize)]
struct BlockEntry {
    name: String,
    seed: Value,
    ops: Vec<Value>,
    state: Value,
    /// Ops Source reported and skipped; the ops after each still applied.
    refused: Vec<usize>,
    refs: Vec<String>,
}

fn block_editor() -> Editor {
    crate::node_ids::NodeIdPlugin::register(
        surface::preset_builder_with_mode(EditorType::MarkdownSync, EditorMode::ViewAttached)
            .extension_state(crate::NodeClock(std::sync::Arc::new(|| 1234))),
        &BLOCK_ID_CLASSES,
        None,
        [5; 32],
    )
    .build()
    .expect("surface")
}

/// Seed ids and op refs stay verbatim; every other id is renamed `<newN>` in
/// document order, so freshly minted ids compare one to one, not as one bucket.
fn minted_bijection(value: &Value, kept: &HashSet<String>) -> Value {
    fn walk(
        value: &Value,
        kept: &HashSet<String>,
        names: &mut std::collections::HashMap<String, String>,
    ) -> Value {
        match value {
            Value::Array(items) => {
                Value::Array(items.iter().map(|v| walk(v, kept, names)).collect())
            }
            Value::Object(map) => {
                let mut out = serde_json::Map::new();
                // Own id first, then children, so numbering follows document order.
                if let Some(Value::Object(state)) = map.get("$") {
                    let mut state = state.clone();
                    if let Some(Value::String(id)) = state.get("id")
                        && !kept.contains(id)
                    {
                        let next = format!("<new{}>", names.len());
                        let name = names.entry(id.clone()).or_insert(next).clone();
                        state.insert("id".into(), Value::String(name));
                    }
                    out.insert("$".into(), Value::Object(state));
                }
                for (key, child) in map {
                    if key != "$" {
                        out.insert(key.clone(), walk(child, kept, names));
                    }
                }
                Value::Object(out)
            }
            other => other.clone(),
        }
    }
    walk(value, kept, &mut std::collections::HashMap::new())
}

/// Every id in document order, duplicates kept.
fn id_list(value: &Value, ids: &mut Vec<String>) {
    match value {
        Value::Array(items) => items.iter().for_each(|item| id_list(item, ids)),
        Value::Object(map) => {
            if let Some(Value::String(id)) = map.get("$").and_then(|state| state.get("id")) {
                ids.push(id.clone());
            }
            for (key, child) in map {
                if key != "$" {
                    id_list(child, ids);
                }
            }
        }
        _ => {}
    }
}

/// Oracle control: the raw Source JSON must survive a native import and export
/// unchanged, or the parity comparison below would compare a native projection.
#[test]
fn source_block_states_survive_native_import_unchanged() {
    let corpus: Vec<BlockEntry> = serde_json::from_str(BLOCK_CORPUS).expect("corpus");
    let mut deltas = Vec::new();
    for entry in &corpus {
        for (label, raw) in [("seed", &entry.seed), ("state", &entry.state)] {
            let mut editor = block_editor();
            load(&mut editor, raw);
            let exported = export(&editor);
            if &exported != raw {
                deltas.push(format!(
                    "{} [{label}]\n  raw    {raw}\n  native {exported}",
                    entry.name
                ));
            }
        }
    }
    assert!(
        deltas.is_empty(),
        "{} projection deltas:\n{}",
        deltas.len(),
        deltas.join("\n")
    );
}

/// Per-case outcome against the raw Source state. Cases Source applies fully are
/// positive-support checks; cases Source stops at op k are refusal-equivalence
/// checks (failedAt only, not typed-cause parity, which has its own tests).
#[test]
fn block_ops_reach_the_source_doc_state() {
    let corpus: Vec<BlockEntry> = serde_json::from_str(BLOCK_CORPUS).expect("corpus");
    assert!(!corpus.is_empty());
    let mut rows = Vec::new();
    let mut failed = 0;
    for entry in corpus {
        let class = if entry.refused.is_empty() {
            "positive".to_string()
        } else {
            format!("refused{:?}", entry.refused)
        };
        let mut kept = HashSet::new();
        collect_ids(&entry.seed, &mut kept);
        let refs: HashSet<String> = entry.refs.iter().cloned().collect();

        let mut native = block_editor();
        load(&mut native, &entry.seed);
        let refused = replay(&mut native, &entry.ops);
        let exported = export(&native);

        // Lineage on raw values, before any renaming.
        let mut problems = Vec::new();
        for (side, value) in [("native", &exported), ("source", &entry.state)] {
            let mut ids = Vec::new();
            id_list(value, &mut ids);
            let unique: HashSet<&String> = ids.iter().collect();
            if unique.len() != ids.len() {
                problems.push(format!("{side} has duplicate ids"));
            }
        }
        let (mut native_ids, mut source_ids) = (Vec::new(), Vec::new());
        id_list(&exported, &mut native_ids);
        id_list(&entry.state, &mut source_ids);
        let native_set: HashSet<&String> = native_ids.iter().collect();
        let source_set: HashSet<&String> = source_ids.iter().collect();
        for id in kept.iter().chain(refs.iter()) {
            if native_set.contains(id) != source_set.contains(id) {
                problems.push(format!(
                    "id {id}: native {} source {}",
                    native_set.contains(id),
                    source_set.contains(id)
                ));
            }
        }
        if refused != entry.refused {
            problems.push(format!(
                "refused native {refused:?} source {:?}",
                entry.refused
            ));
        }
        let mut stable = kept.clone();
        stable.extend(refs);
        let actual = minted_bijection(&exported, &stable);
        let expected = minted_bijection(&entry.state, &stable);
        if actual != expected {
            problems.push(format!("state\n    native {actual}\n    source {expected}"));
        }
        let outcome = if problems.is_empty() {
            "match".to_string()
        } else {
            failed += 1;
            format!("MISMATCH: {}", problems.join("; "))
        };
        rows.push(format!("{class:<11} {}: {outcome}", entry.name));
    }
    // The per-case table is the receipt; print it on success too (`--nocapture`).
    eprintln!("block corpus outcomes:\n{}", rows.join("\n"));
    assert!(
        failed == 0,
        "{failed} of {} cases differ:\n{}",
        rows.len(),
        rows.join("\n")
    );
}

const SELECTION_CORPUS: &str = include_str!("corpus/selection.json");

/// Node key at a child-index path from the root.
fn at_path(editor: &Editor, path: &[u64]) -> NodeKey {
    let view = editor.state().view();
    let mut key = NodeKey::ROOT;
    for index in path {
        let index = usize::try_from(*index).expect("index");
        key = view.children(key).nth(index).expect("path exists");
    }
    key
}

fn path_of(value: &Value) -> Vec<u64> {
    value
        .as_array()
        .expect("path")
        .iter()
        .map(|i| i.as_u64().expect("index"))
        .collect()
}

/// Source MarkdownPopup ids for stored table and in-table range selections,
/// transcribed from the live OFF capture named in the corpus `evidence`.
#[test]
fn selected_block_ids_match_source_for_table_selections() {
    let corpus: Value = serde_json::from_str(SELECTION_CORPUS).expect("corpus");
    let mut rows = Vec::new();
    let mut failed = 0;
    for case in corpus["cases"].as_array().expect("cases") {
        let mut native = block_editor();
        load(&mut native, &corpus["seed"]);
        let selection = &case["selection"];
        let chosen = match selection["kind"].as_str() {
            Some("table") => {
                let anchor = at_path(&native, &path_of(&selection["anchor"]));
                let focus = at_path(&native, &path_of(&selection["focus"]));
                let table = at_path(&native, &path_of(&selection["anchor"])[..1]);
                Selection::Table(TableSelection::new(table, anchor, focus))
            }
            _ => {
                let point = |side: &Value| {
                    let key = at_path(&native, &path_of(&side["path"]));
                    let offset =
                        u32::try_from(side["offset"].as_u64().expect("offset")).expect("u32");
                    Point::text(key, Utf16Offset(offset))
                };
                Selection::Range(RangeSelection::new(
                    point(&selection["anchor"]),
                    point(&selection["focus"]),
                ))
            }
        };
        native
            .update(|tx| {
                tx.set_selection(Some(chosen))?;
                Ok(())
            })
            .expect("select");
        let expected: Vec<Value> = case["expected"]
            .as_array()
            .expect("expected")
            .iter()
            .map(|path| {
                let key = at_path(&native, &path_of(path));
                let id = crate::node_ids::get_id(native.state().view(), key)
                    .expect("id read")
                    .expect("seed node has an id");
                Value::String(id.into())
            })
            .collect();
        let actual = surface::query(
            "group-c.selected-block-ids",
            &Value::Null,
            0,
            native.state(),
        )
        .expect("query")
        .expect("registered query");
        let name = case["name"].as_str().unwrap_or("?");
        if actual == Value::Array(expected.clone()) {
            rows.push(format!("match    {name}"));
        } else {
            failed += 1;
            rows.push(format!(
                "MISMATCH {name}\n    native {actual}\n    source {}",
                Value::Array(expected)
            ));
        }
    }
    eprintln!("selection corpus outcomes:\n{}", rows.join("\n"));
    assert!(failed == 0, "{failed} cases differ:\n{}", rows.join("\n"));
}
